'use strict';
const gameFonts=[{id:'GamePretendard',name:'Pretendard',url:'https://github.com/orioncactus/pretendard'},{id:'GameSUIT',name:'SUIT',url:'https://github.com/sun-typeface/SUIT'},{id:'GameNoto',name:'Noto Sans KR',url:'https://github.com/google/fonts/tree/main/ofl/notosanskr'},{id:'GameNanum',name:'나눔고딕',url:'https://github.com/google/fonts/tree/main/ofl/nanumgothic'},{id:'GameGothicA1',name:'Gothic A1',url:'https://github.com/google/fonts/tree/main/ofl/gothica1'}];
let chosenGameFont='GamePretendard';
try{const stored=localStorage.getItem('autochess-ui-font');if(gameFonts.some(f=>f.id===stored))chosenGameFont=stored;}catch{}
document.documentElement.style.setProperty('--ui-font',chosenGameFont);
function fontLabMarkup(){return `<section class="font-lab"><h3>글꼴 테스트</h3><label for="fontSampleInput">같은 문장으로 비교</label><input id="fontSampleInput" type="text" maxlength="120" value="동료를 모으고 새로운 조합을 완성하세요. 123,456G"><div class="font-samples">${gameFonts.map(f=>`<article class="font-sample" data-font-card="${f.id}" data-active="${chosenGameFont===f.id}"><div class="font-sample-head"><b>${f.name}</b><button data-apply-font="${f.id}" aria-pressed="${chosenGameFont===f.id}">${chosenGameFont===f.id?'적용 중':'게임에 적용'}</button></div><p class="font-sample-text" style="font-family:${f.id},sans-serif">동료를 모으고 새로운 조합을 완성하세요. 123,456G</p></article>`).join('')}</div><p class="font-lab-links">무료 배포 · SIL OFL 1.1<br>${gameFonts.map(f=>`<a href="${f.url}" target="_blank" rel="noopener">${f.name} 출처 ↗</a>`).join('')}</p></section>`;}
document.addEventListener('input',e=>{if(e.target.id==='fontSampleInput')for(const sample of document.querySelectorAll('.font-sample-text'))sample.textContent=e.target.value;});
document.addEventListener('click',e=>{const button=e.target.closest('[data-apply-font]');if(!button||!gameFonts.some(f=>f.id===button.dataset.applyFont))return;chosenGameFont=button.dataset.applyFont;document.documentElement.style.setProperty('--ui-font',chosenGameFont);try{localStorage.setItem('autochess-ui-font',chosenGameFont);}catch{}for(const card of document.querySelectorAll('[data-font-card]')){const active=card.dataset.fontCard===chosenGameFont;card.dataset.active=String(active);const apply=card.querySelector('[data-apply-font]');apply.textContent=active?'적용 중':'게임에 적용';apply.setAttribute('aria-pressed',String(active));}});
